#!/usr/bin/env node
// Reads /tmp/new-works.json (output of the prior workflow step), and
// writes one MDX skeleton per new OpenAlex work into
// src/content/publications/_drafts/. Each draft is auto-generated and
// REQUIRES the owner to fill in topics, methods, tldr, and abstract
// before being moved out of _drafts and published.
//
// Used by .github/workflows/update-metrics.yml. Lives in its own file
// (rather than inline `node -e "..."` in the workflow) because the
// previous inline approach mixed backticks and ${} between bash and
// JavaScript, which produced a syntax error the moment the script was
// non-trivial. A standalone .mjs file lets us write idiomatic JS with
// none of the cross-language quoting traps.

import fs from 'node:fs';
import path from 'node:path';

const NEW_WORKS_PATH = '/tmp/new-works.json';
const DRAFTS_DIR = 'src/content/publications/_drafts';
const MY_ORCID = '0000-0002-3296-6518';

const newWorks = JSON.parse(fs.readFileSync(NEW_WORKS_PATH, 'utf8'));
if (newWorks.length === 0) {
  console.log('No new works to draft.');
  process.exit(0);
}

fs.mkdirSync(DRAFTS_DIR, { recursive: true });

const TYPE_MAP = {
  'journal-article': 'article',
  'book-chapter': 'chapter',
  'book': 'book',
  'edited-book': 'edited-book',
  'proceedings-article': 'conference',
};

// YAML-escape: just the double quote and backslash; the rest is safe
// inside a "..." scalar. Newlines in source titles are rare but we
// collapse them to spaces just in case.
function yamlEscape(s) {
  return String(s ?? '').replace(/[\r\n]+/g, ' ').replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function slugify(title) {
  return String(title)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 60);
}

for (const w of newWorks) {
  const doi = String(w.doi || '').replace('https://doi.org/', '');
  const year = w.publication_year || new Date().getFullYear();
  const title = w.title || 'Untitled';
  const slug = slugify(title);
  // id must be unique and stable; prefer DOI-derived id, fall back to slug.
  const id = doi ? doi.replace(/[^a-z0-9]/gi, '-').toLowerCase() : slug;

  const authors = (w.authorships || []).map((a) => {
    const name = a.author?.display_name || 'Unknown';
    const isMe = String(a.author?.orcid || '').includes(MY_ORCID);
    return { name, isMe };
  });

  const venue = w.primary_location?.source?.display_name || '';
  const type = TYPE_MAP[w.type] || 'article';

  const authorsYaml = authors
    .map((a) => `  - name: "${yamlEscape(a.name)}"${a.isMe ? '\n    isMe: true' : ''}`)
    .join('\n');

  const mdx = [
    '---',
    `id: "${yamlEscape(id)}"`,
    `slug: "${yamlEscape(slug)}"`,
    `title: "${yamlEscape(title)}"`,
    `year: ${year}`,
    'authors:',
    authorsYaml,
    `type: ${type}`,
    'status: published',
    `venue: "${yamlEscape(venue)}"`,
    `doi: "${yamlEscape(doi)}"`,
    'topics: []     # TODO: add topic ids from src/data/topics.ts before publishing',
    'methods: []    # TODO: add methods if applicable',
    'featured: false',
    'abstract: ""',
    'tldr: ""',
    '---',
    '',
    '<!-- Auto-generated by .github/workflows/update-metrics.yml. Fill in topics, methods, abstract, and tldr before moving out of _drafts. -->',
    '',
  ].join('\n');

  const outPath = path.join(DRAFTS_DIR, `${slug}.mdx`);
  fs.writeFileSync(outPath, mdx);
  console.log(`Created: ${outPath}`);
}
